from __future__ import annotations

import json
import sys
import warnings
from pathlib import Path

import numpy as np

TASK_DIR = Path(__file__).resolve().parent
SOURCE_ROOT = TASK_DIR / "source" / "src"
if str(SOURCE_ROOT) not in sys.path:
    sys.path.insert(0, str(SOURCE_ROOT))

from xarray import Dataset, date_range  # noqa: E402


REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def write_report(report: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def build_case() -> Dataset:
    time = date_range(start="0001-01-01", periods=40, freq="D")
    return Dataset(
        {"pr": ("time", np.arange(40, dtype=float))},
        coords={"time": time},
    )


def run_public_workflow() -> dict[str, object]:
    case = build_case()
    observation: dict[str, object] = {
        "input_length": int(case.sizes["time"]),
    }

    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        try:
            resampled = case.resample(time="Q-DEC").mean()
        except Exception:  # noqa: BLE001
            observation.update(
                {
                    "workflow_stage": "aggregation",
                    "result": "did_not_complete",
                }
            )
            return {
                "schema_version": "1.0",
                "status": "pre_fix_expected_failure",
                "observation": observation,
            }

    values = np.asarray(resampled["pr"].values, dtype=float)
    observation.update(
        {
            "output_length": int(resampled.sizes["time"]),
            "output_values": values.tolist(),
            "output_total": float(values.sum()),
        }
    )
    return {
        "schema_version": "1.0",
        "status": "workflow_completed",
        "observation": observation,
    }


def main() -> int:
    try:
        report = run_public_workflow()
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    exit_code = 0 if report["status"] == "workflow_completed" else 1
    return write_report(report, exit_code)


if __name__ == "__main__":
    raise SystemExit(main())

